     "a": 3,
     "e": "本题考查政治常识。 ①正确，2021 年1 月，中央纪委国家监委在《知信行|如何正确理解四项监督逻辑关系》 中指出：“党的十九大以来，纪律监督、监察监督、派驻监督、巡视监督‘四项监督’全覆 盖总体格局逐步形成，监督合力不断增强，在党和国家监督体系中的支柱作用日益彰显。” ②正确，党的二十大报告在“十五、坚定不移全面从严治党，深入推进新时代党的建设 新的伟大工程”中的“（三）完善党的自我革命制度规范体系”部分指出：“健全党统一领 导、全面覆盖、权威高效的监督体系，完善权力监督制约机制，以党内监督为主导，促进各 类监督贯通协调，让权力在阳光下运行。” ③错误，④正确，2023 年12 月，中央纪委国家监委在《新视野|坚持完善党和国家监 督体系》中指出：“坚持完善党和国家监督体系的目标任务是实现对权力运行的监督全覆盖， 所有党员干部和行使公权力的公职人员都是党和国家监督体系的覆盖对象。” ⑤正确，2020 年4 月，中央纪委国家监委在《健全党和国家监督体系的要求》中指出： “‘党统一领导’是基本前提，强调党和国家监督必须在党中央直接领导下开展工作。‘全 面覆盖’是监督范围，要求监督监察职能覆盖各级党组织和党员、覆盖所有行使公权力的公 职人员，消除权力监督的真空地带。‘权威高效’是运行机制，要求把制度优势转化为治理 效能。纪检监察机关必须围绕监督体系要求，统筹推进纪检监察体制改革。” 故①②④⑤表述正确。 故正确答案为D。"
