     "a": 0,
     "e": "本题考查政治常识。 ①正确，习近平总书记在中央全面深化改革委员会第二次会议强调，建设更高水平开放 型经济新体制是我们主动作为以开放促改革、促发展的战略举措，要围绕服务构建新发展格 局，以制度型开放为重点，聚焦投资、贸易、金融、创新等对外交流合作的重点领域深化体 制机制改革。《求是》杂志《建设更高水平开放型经济新体制》文章中“二、建设更高水平 开放型经济新体制的重点任务”部分指出：“逐步推进金融领域开放，构建公平有序的金融 生态环境，深化境内外资本市场互联互通，在持续评估和有效管控风险的基础上，提升金融 机构国际化经营水平，有序放宽证券业股比限制，稳妥推进银行业对外开放，健全合格境外 投资者制度。”促进金融保险业的全面开放有利于建设更高水平开放型经济新体制。 ②正确，中央全面深化改革委员会第二次会议指出，当前，我国发展面临复杂严峻的国 际形势。要完善开放型经济新体制的顶层设计，深化贸易投资领域体制机制改革。《“十四 五”对外贸易高质量发展规划》中“三、重点任务（十）营造良好发展环境”部分指出： “积极参与国际经贸规则制定。坚定支持多边贸易体制，维护世界贸易组织基本原则，积极 参与世界贸易组织改革，继续推动恢复上诉机构正常运行，建设性参与渔业补贴、投资便利 化、电子商务、服务贸易国内规制、中小微企业、贸易与环境等议题谈判和讨论。”积极参 与国际贸易规则的制定有利于建设更高水平开放型经济新体制。 ③正确，中央全面深化改革委员会第二次会议指出，要完善开放型经济新体制的顶层设 计······全面优化营商环境，完善服务保障体系，充分发挥我国综合优势，以国内大 循环吸引全球资源要素，提升贸易投资合作质量和水平。2021 年6 月2 日，李克强总理在 全国深化“放管服”改革着力培育和激发市场主体活力电视电话会议上发表重要讲话，部署 持续一体推进“放管服”改革，打造市场化法治化国际化营商环境，培育壮大市场主体，更 大程度激发市场活力和社会创造力。营造国际化法治化便利化营商环境有利于建设更高水平 开放型经济新体制。 ④错误， 《中共中央国务院关于新时代加快完善社会主义市场经济体制的意见》中“一、 总体要求”部分指出：“坚持扩大高水平开放和深化市场化改革互促共进。坚定不移扩大开 放，推动由商品和要素流动型开放向规则等制度型开放转变，吸收借鉴国际成熟市场经济制 度经验和人类文明有益成果，加快国内制度规则与国际接轨，以高水平开放促进深层次市场 化改革。” 故①②③表述正确。 故正确答案为A。"
