     "a": 2,
     "e": "本题考查政治常识。 A 项正确，“十三五”以来，我国基本公共服务制度体系建设和基本公共服务均等化工 作取得了一系列突出成就，建成了世界上规模最大的社会保障体系。 B 项正确，党的十九届五中全会明确了“十四五”时期我国社会保障事业发展的蓝图。 总书记告诫全党：“经济发展和社会保障是水涨船高的关系，水浅行小舟，水深走大船，违 背规律就会搁浅或翻船。” C 项错误，中国要建立的是多层次的养老保险、医疗保障、社会救助、养老服务及住房 保障等体系，其实质是要在夯实政府负责或主导的法定社会保障制度的同时，充分发挥市场 主体与社会力量的积极性，通过市场机制与慈善机制更多更好地配备资源，进而持续壮大社 会保障体系的物质基础，这构成了社会保障可持续发展和满足人民群众日益增长的美好生活 需要的必要条件。故我国社会保障体系以政府为主导，并非以市场主体和社会力量承担的保 障为核心。 D 项正确，目前，我国以社会保险为主体，包括社会救助、社会福利、社会优抚等制度， 功能完备的社会保障体系基本建成，基本医疗保险覆盖13.6 亿人，基本养老保险覆盖近10 亿人，是世界上规模最大的社会保障体系。 本题为选非题，故正确答案为C。"
