     "e": "本题考查政治常识。 2022 年12 月，中共中央、国务院印发了《扩大内需战略规划纲要（2022-2035 年）》 （以下简称《纲要》）。 ①错误，《纲要》中“九、扎实推动共同富裕，厚植内需发展潜力”部分指出：“······坚 持以人民为中心的发展思想，在高质量发展中促进共同富裕，正确处理效率和公平的关系， 完善收入分配格局，构建初次分配、再分配、三次分配协调配套的基础性制度安排，加大税 收、社保、转移支付等调节力度并提高精准性，扩大中等收入群体比重，增加低收入群体收 入，合理调节高收入，取缔非法收入，促进社会公平正义，促进人的全面发展，增强内需发 展后劲。” ②正确，《纲要》中“九、扎实推动共同富裕，厚植内需发展潜力”部分的“（二十八） 持续优化初次分配格局”中指出：“健全各类生产要素参与分配机制。构建知识、技术、数 据等创新要素参与收益分配机制，强化以增加知识价值为导向的分配政策，发挥工资激励保 障作用。” ③正确，《纲要》中“九、扎实推动共同富裕，厚植内需发展潜力”部分的“（二十九） 逐步健全再分配机制”中指出：“加大财税制度对收入分配的调节力度。健全直接税体系， 完善综合与分类相结合的个人所得税制度，加强对高收入者的税收调节和监管。完善中央与 地方财政事权和支出责任划分，推动教育、养老、医疗、住房保障等基本公共服务均等化。” ④错误，《纲要》中“九、扎实推动共同富裕，厚植内需发展潜力”部分的“（二十九） 逐步健全再分配机制”中指出：“健全社会保障制度。推进基本养老保险由制度全覆盖到法 定人群全覆盖，完善灵活就业人员参加职工社会保险制度。发展企业年金、职业年金，规范 发展第三支柱养老保险。” 故②③表述正确。 故正确答案为C。"
