     "e": "本题考查中国特色社会主义理论体系。 A 项正确，以民为本、以民为先是中国传统执政理念。“民惟邦本，本固邦宁”“仁者 爱人”“先天下之忧而忧，后天下之乐而乐”等理念主张，体现了古代先哲心系于民、顺应 民心的情怀，发挥了建构社会、稳定社会、校正社会的重要作用。在推进中国式现代化的进 程中，中国共产党坚持以马克思主义为指导，继承传统民本思想的合理内核，并进行创造性 转化、创新性发展，形成了“坚持人民至上”的价值追求，为坚持以人民为中心推进“人口 规模巨大的现代化”提供了丰厚文化滋养和坚实理论基础。 B 项错误，“天下大同”寄予中华民族对未来美好社会的理想。“民亦劳止，汔可小 康”“治国之道，富民为始”等表达了我们祖先对强国富民的憧憬。“全体人民共同富裕的 现代化”是这一理念的升华。可以说，共同富裕是中华民族自古以来的社会理想，也是中国 共产党矢志不渝的奋斗目标。作为马克思主义政党，我们党始终把实现人民对美好生活的向 往作为现代化建设的出发点和落脚点，坚定不移以中国式现代化扎实推进全体人民共同富 裕。 C 项错误，“仓廪实而知礼节，衣食足而知荣辱”揭示了物质文明与精神文明的关系。 中华文明历来重视人的精神生活，既追求丰衣足食，又追求人格尊严，讲究仁义礼智信，期 盼社会和谐，憧憬物质生活充实、道德境界高尚、社会公平正义的大同世界。中国式现代化 是“物质文明和精神文明相协调的现代化”，正是契合了这一文化传统。 D 项错误，“天人合一”表达了对人与自然关系的认识。中华文化强调“天人合一”， 孟子提出“不违农时，谷不可胜食也；数罟不入洿池，鱼鳖不可胜食也；斧斤以时入山林， 材木不可胜用也”，是天人合一思想在先秦时期的朴素表达。明确提出天人合一思想的汉代 董仲舒认为：“天亦有喜怒之气，哀乐之心，与人相副，以类合之，天人一也。”这些观念 表现出中华民族对人与自然是生命共同体的深刻认识，以及对风调雨顺、河清海晏、人与自 然和谐共生的太平景象的向往和追求。这些理念，为中国式现代化确立绿色发展的价值理念 和走人与自然和谐共生的可持续发展路径奠定了文化根基。 故正确答案为A。"
