     "a": 2,
     "e": "本题考查中国特色社会主义理论体系。 人民政协是中国人民爱国统一战线组织，各民主党派对国家大政方针和群众生活的重要 问题进行政治协商，并通过建议和批评发挥参政议政、民主监督的作用。人民政协的两大主 题是团结和民主。人民政协的主要职能是政治协商、民主监督、参政议政。 A 项错误，政治协商是对国家和地方的大政方针以及政治、经济、文化和社会生活中的 重要问题在决策之前进行协商和就决策执行过程中的重要问题进行协商。 B 项错误，人民政协民主监督的主要内容为对国家宪法、法律和法规的实施情况进行监 督，对重大方针政策的贯彻执行情况进行监督，对国家机关及其工作人员的工作情况进行监 督。 C 项正确，参政议政是对政治、经济、文化、社会生活和生态环境等方面的重要问题以 及人民群众普遍关心的问题，开展调查研究，反映社情民意，进行协商讨论。通过调研报告、 提案、建议案或其他形式，向中国共产党和国家机关提出意见和建议。题干主要体现了政协 的参政议政职能。 D 项错误，开展对外交往并非人民政协的主要职能。 故正确答案为C。"
