     "a": 2,
     "e": "本题考查中国特色社会理论体系。 A 项错误，科学发展观，第一要义是发展，核心是以人为本，基本要求是全面协调可持 续发展，根本方法是统筹兼顾。 B 项错误，2001 年，江泽民在建党80 周年的讲话上，全面阐述了“三个代表”的科学 内涵和基本内容，即中国共产党必须始终代表中国先进生产力的发展要求，代表中国先进文 化的前进方向，代表中国最广大人民的根本利益。“三个代表”重要思想，正确回答了在新 的历史条件下，“建设什么样的党，怎样建设党”这一重大问题。 C 项正确，习近平总书记在党的十九大报告指出：“坚持人与自然和谐共生。建设生态 文明是中华民族永续发展的千年大计。必须树立和践行绿水青山就是金山银山的理念，坚持 节约资源和保护环境的基本国策。” D 项错误，党的十三大明确规定：“在社会主义初级阶段，我们党的建设有中国特色的 社会主义的基本路线是：领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则， 坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代 化国家而奋斗。”故“以经济建设为中心、坚持改革开放”属于邓小平理论的内容。 故正确答案为C。"
