     "e": "本题考查法理学。 A、C、D 三项正确，用制度保障领导干部发挥“关键少数”作用包括以下三个方面： （一）党政主要负责人履行推进法治建设第一责任人职责； （二）把能不能遵守法律、依法办事作为考察干部的重要内容； （三）法治之下，没有免罪的“丹书铁券”，也没有“铁帽子王”。在法治国家，任何 人都没有法律之外的绝对权力，绝不允许以言代法、以权压法、逐利违法、徇私枉法。 B 项错误，我们党选拔任用干部的标准就是德才兼备，而法治观念、法治素养是干部德 才的重要内容。必须把能不能遵守法律、依法办事作为考察干部重要内容，相同条件下，优 先提拔使用法治素养好、依法办事能力强的干部。 本题为选非题，故正确答案为B。"
