     "a": 0,
     "e": "第一步，本题考查新时代中国特色社会主义思想知识。 第二步，全面从严治党，重在加强纪律建设。习近平总书记指出：“党面临的形 势越复杂、肩负的任务越艰巨，就越要加强纪律建设，越要维护党的团结统一， 确保全党统一意志、统一行动、步调一致前进。” 因此，选择A 选项。 【拓展】纪律是党的生命所系、力量所在。马克思指出，“必须绝对保持党的纪 律，否则将一事无成”。从严抓好党的纪律建设，是党长期奋斗的经验总结，是 党管党治党规律性认识，也是党不断从胜利走向胜利的重要保障。"
