     "a": 1,
     "e": "第一步，本题考查中国历史知识。 第二步，1992 年，海协会与台湾海基会受权就在两岸事务性商谈中表述坚持一 个中国原则事宜进行协商。经过1992 年10 月香港会谈及其后一系列函电往来， 达成了各自以口头方式表述“海峡两岸均坚持一个中国原则”的共识，后来被概 括为“九二共识”。一国两制，即“一个国家，两种制度”，是中国政府为实现国 家和平统一而提出的基本国策，后发展为法律文件。“九二共识”并不是中国政 府提出的，“一国两制”是中国政府提出的。 因此，选择B 选项。 【拓展】ACD 项：“一国两制”与“九二共识”均以尊重历史和现实为依据，以 维护祖国和中华民族的根本利益为出发点，并且都在一定范围内得到了实践。 ACD 是两者的相似之处，因此排除。"
