     "e": "第一步，本题考查新时代中国特色社会主义思想知识。 第二步，C 项：党的十九大报告提出了十四条新时代坚持和发展中国特色社会主 义的基本方略，属于“坚持推动构建人类命运共同体”的具体内容是：坚持独立 自主的和平外交政策，推动构建新型国际关系。始终不渝走和平发展道路、奉行 互利共赢的开放战略，坚定维护国际关系基本准则，维护国际公平正义。 因此，选择C 选项。 【拓展】A 项：2007 年党的十七大报告提出，要健全民主制度，丰富民主形式， 拓宽民主渠道，依法实行民主选举、民主决策、民主管理、民主监督，保障人民 的知情权、参与权、表达权、监督权。A 项错误。 B 项：党的十八届六中全会通过的《关于新形势下党内政治生活的若干准则》， 全面总结近年来特别是党的十八大以来管党治党的新鲜经验，顺应时代发展变化 对全面从严治党提出的新要求，对加强和规范党内政治生活的重点内容、主要任 务、重要举措作出系统部署，是指导新形势下全面从严治党的行动纲领，是严肃 党内政治生活、净化党内政治生态的根本遵循，是增强党内政治生活的政治性、 时代性、原则性、战斗性的强大武器。我们要把学习贯彻《准则》作为当前全党 的重大政治任务抓紧抓实抓好。B 项错误。 D 项：统筹发展和安全，增强忧患意识，做到居安思危，是我们党治国理政的一 个重大原则。党的十九届五中全会审议通过的《中共中央关于制定国民经济和社 会发展第十四个五年规划和二〇三五年远景目标的建议》，注重处理好发展和安 全的关系，就统筹发展和安全、建设更高水平的平安中国提出明确要求、作出工 作部署，对在复杂环境下更好推进我国经济社会发展具有重大指导意义。D 项错 误。"
