     "e": "第一步，本题考查新时代中国特色社会主义思想知识并选错误项。 第二步，以经济建设为中心，坚持四项基本原则，坚持改革开放，是社会主义初 级阶段的基本路线。坚持以经济建设为中心与改革开放的历史进程、目标与任务 要求密切相关。党的十一届三中全会把党和国家工作中心从“以阶级斗争为纲” 转移到“以经济建设为中心”，实现了新中国成立以来党的历史上具有深远意义 的伟大转折。 因此，选择A 选项。 【拓展】十四个坚持：（一）坚持党对一切工作的领导。党政军民学，东西南北 中，党是领导一切的。（二）坚持以人民为中心。（三）坚持全面深化改革。（四） 坚持新发展理念。（五）坚持人民当家作主。（六）坚持全面依法治国。（七）坚 持社会主义核心价值体系。（八）坚持在发展中保障和改善民生。（九）坚持人与 自然和谐共生。（十）坚持总体国家安全观。（十一）坚持党对人民军队的绝对领 导。（十二）坚持“一国两制”和推进祖国统一。（十三）坚持推动构建人类命运 共同体。（十四）坚持全面从严治党。"
