     "e": "第一步，本题考查新时代中国特色社会主义思想知识。 第二步，习近平法治思想的核心要义集中体现在“十一个坚持”：（1）坚持党对 全面依法治国的领导；（2）坚持以人民为中心；（3）坚持中国特色社会主义法治 道路；（4）坚持依宪治国、依宪执政（①项正确）；（5）坚持在法治轨道上推进 国家治理体系和治理能力现代化（③项正确）；（6）坚持建设中国特色社会主义 法治体系（②项正确）；（7）坚持依法治国、依法执政、依法行政，共同推进法 治国家、法治政府、法治社会一体建设；（8）坚持全面推进科学立法、严格执法、 公正司法、全民守法（④项正确）；（9）坚持统筹推进国内法治和涉外法治；（10） 坚持建设德才兼备的高素质法制工作队伍；（11）坚持抓住领导干部这个“关键 少数”。所以，①②③④项正确。 因此，选择D 选项。"
