     "e": "第一步，本题考查法理学并选错误项。 第二步，党的十八届四中全会通过的《决定》指出，建设中国特色社会主义法治 体系，必须坚持立法先行，发挥立法的引领和推动作用，抓住提高立法质量这个 关键；实现立法和改革决策相衔接，做到重大改革于法有据、立法主动适应改革 和经济社会发展需要。 因此，选择C 选项。 【拓展】2014 年10 月20 日至23 日举行的中国共产党第十八届中央委员会第四 次全体会议中提出“法律是治国之重器，良法是善治之前提。”发挥立法的引领 和推动作用。"
