     "a": 0,
     "e": "A 项： 矛盾的普遍性即事事有矛盾、时时有矛盾，这是所有矛盾都具有的共性特点；而 矛盾的特殊性是指不同事物的矛盾及每一侧面各有其特点，也就是矛盾的个性表 现。所以该选项说法正确。 B 项: 矛盾的普遍性是无条件的、绝对的，矛盾存在于一切事物中，贯穿于每一事物发 展过程的始终；而矛盾的特殊性是有条件的、相对的，它随着条件的变化而变化。 所以B 项:说法错误。 C 项: 矛盾是客观的，是事物本身所固有的，不以人的意志为转移，它独立于人的认知、 情感、意志等主观因素而存在，并非从属于主观性。所以C 项:错误。 D 项: 事物的性质主要是由主要矛盾的主要方面决定的，而不是由矛盾的普遍性、客观 性决定的。矛盾的普遍性和客观性要求我们承认矛盾、分析矛盾、解决矛盾，但 不是认清事物本质和发展规律的直接决定因素。所以D 项:错误。"
