     "e": "2026年6月1日，李强签署国务院令，公布《国务院关于对外投资的规定》，自2026年7月1日起施行。《规定》旨在推进高水平对外开放，促进对外投资高质量发展，有效实施对外投资管理，保护投资者及其对外投资合法权益，维护国家主权、安全、发展利益。《规定》明确对外投资适用范围。对外投资即境外投资，中国境内投资者直接或者间接获得其他国家（地区）的企业、资产等相关权益的活动适用本规定。对投资者在港澳台投资的管理参照本规定执行。《规定》明确对外投资总体要求。对外投资工作贯彻总体国家安全观，健全对外投资管理服务体系，提升对外投资质量与水平。主动对接国际高标准经济贸易规则，推进高质量共建“一带一路”，推动产业链供应链国际合作。支持投资者按照市场化原则开展对外投资活动。《规定》明确有效实施管理。完善调控措施，分类分级实施全过程监管，加强风险防控，提高对外投资科学性、安全性。国务院有关部门制定、调整和实施对外投资政策，指导、监督投资者规范投资经营行为。投资者应当依照国家有关规定办理核准备案、信息报告、跨境资金登记等手续。强化投资者主体责任，不得扰乱对外投资市场秩序。《规定》明确强化对外投资保护。国务院有关部门加强监测预警和风险评估，指导和帮助投资者做好安全风险防范。建立投资壁垒调查制度等，切实维护投资者及其对外投资的安全和正当权益以及国家的海外利益。B项错误，支持投资者按照市场化原则开展对外投资活动。故本题选B。"
