     "e": "2026年6月11日，深圳医学科学院表示，该院颜宁、范潇、黄健联合团队聚焦人体神经系统中重要的电压门控钠离子通道Nav1.6，揭示了三种来自动物的激动型多肽神经毒素对钠离子通道的调控机制，为神经系统疾病精准药物研发开辟了新路径。相关研究成果日前在线发表于国际期刊《自然》。在此次研究中，科研人员发现，蝎毒Cn2、芋螺毒素ι-RXIA、子弹蚁毒素Pc1a三种激动型神经毒素能调控Nav1.6，但调控的方式各不相同：蝎毒Cn2依托通道自身糖链完成结合；芋螺毒素ι-RXIA像绳索一样把不同的电压感受结构域绑定在一起；子弹蚁毒素Pc1a嵌入细胞膜界面，改变通道开合节奏。此次研究成果清晰阐明了天然毒素调控神经通道的多样模式，为设计更精准、安全的Nav1.6靶向药物提供了坚实的结构基础。故本题选C。"
