     "a": 0,
     "e": "2026年6月12日，《细胞》杂志刊文显示，清华大学苏俊研究团队通过先进的长时程显微成像技术，在国际上首次拍摄到人类着床前胚胎发育5天连续过程的高清画面，发现人类胚胎发育停滞“高发”原因。团队系统分析超过150枚人类和食蟹猴胚胎中的2000多次细胞分裂，发现超七成的早期（前3天）停滞胚胎在第二次卵裂时均发生了纺锤体异常。人类胚胎通常会经历多次卵裂，每次卵裂，细胞都需要通过纺锤体将染色体平均分配到两个子细胞。实验结果表明，第二次卵裂时的纺锤体异常会直接导致染色体异常，继而在三次分裂内引发胚胎细胞周期停滞。进一步研究发现，细胞里的“细胞骨架组织中心”，即中心体，对人类着床前胚胎的纺锤体组装至关重要，其数目异常能直接诱导异常纺锤体的发生。基于以上发现，研究人员在第二次卵裂阶段短暂加入半抑制浓度的中心体复制调控蛋白的抑制剂，成功将中心体正常细胞的比例从40%提升至80%，极大降低了胚胎中心体复制错误的发生概率，且不会对中心体数目正常的胚胎细胞产生不良影响。这有望用于早期卵裂停滞的临床防治。故本题选B。"
