     "a": 0,
     "e": "2026年1月4日，《光明日报》报道，第四十三届联合国教科文组织大会近日审议通过，将顾方舟诞辰100周年纪念活动正式纳入联合国教科文组织系列纪念活动。脊髓灰质炎，俗称“小儿麻痹症”，核心危害是侵犯中枢神经系统的运动神经细胞，以其高致残率、高死亡率，曾让无数家庭陷入绝望--1955年，江苏南通暴发大规模脊髓灰质炎疫情，1680例临床报告中，466人不幸夭折，幸存的孩子大多留下终身残疾。1957年，31岁的顾方舟主动请缨，带领研究小组开启了与脊髓灰质炎病毒的殊死较量。为了证明苗的安全性，顾方舟带着自己未满周岁的孩子一起，亲自试药，团队其他同事也纷纷将自己的孩子送来参与试验，凑齐了试验所需的儿童群体。1960年，首批“脊灰”（Sabin型）活疫苗在我国研制成功。后来经过改进，顾方舟又研发了淡黄色的脊髓灰质炎糖丸疫苗，解决了储存运输的难题，并极大提升了接种率。1994年9月，从发现最后一例患者后，我国至今未发现由本土病毒引起的新病例。2000年，“中国消灭脊髓灰质炎证实报告签字仪式”在北京举行，74岁的顾方舟作为代表郑重签名，标志着中国成为无脊髓灰质炎国家。糖丸疫苗以其高效、便捷、低成本的特性，在全球尤其是发展中国家得到广泛应用--在非洲、亚洲的偏远地区，糖丸疫苗无需复杂的冷藏设备即可运输储存，大大降低了接种门槛，帮助这些地区的儿童建立起免疫屏障。2019年1月2日凌晨，92岁的“糖丸爷爷”与世长辞。他光辉灿烂的一生，凝结为一颗小小的糖丸，承载着他对孩子们最深沉的爱，将永远护佑亿万儿童的“脊梁”。故本题选C。"
