     "e": "就业是民生之本，解决就业问题根本要靠发展。《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提出：“构建就业友好型发展方式。”这是深入实施就业优先战略、促进高质量充分就业、推动经济和社会协调发展的重要部署。可以从以下3个方面来理解。第一，准确把握就业友好型发展方式的内涵。就业友好型发展方式，是指能够产生积极的就业带动力，有利于提升就业质量和扩大就业容量的发展方式。它注重高质量发展和高质量充分就业的有机统一。一方面，始终把就业放在发展的优先位置，反对“无就业的增长”，即只顾经济增长却忽视就业甚至排斥就业的做法；另一方面，把高质量发展作为高质量充分就业的基础，反对打着所谓创造就业岗位的旗号保护过剩产能或上马破坏生态环境的产业。第二，深刻认识构建就业友好型发展方式的重要意义。就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发展，事关国家长治久安。广大劳动者不仅希望有活干，而且希望获得更高质量就业岗位。为此，必须构建就业友好型发展方式，在推动高质量发展中持续促进就业质的有效提升和量的合理增长。这是做好新时代就业工作、不断增进民生福祉的必然要求，是防范化解就业矛盾、确保就业形势稳定的必然要求，也是巩固发挥人力资源优势、推进人口规模巨大的现代化的必然要求。第三，抓实抓好构建就业友好型发展方式的政策措施。构建就业友好型发展方式，关键在于推动经济社会发展和就业促进协调联动，依靠高质量发展逐步形成就业机会充分、就业环境公平、就业结构优化、人岗匹配高效、劳动关系和谐的局面。故本题选D。"
