     "e": "《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提出：“实施新时代立德树人工程”。这一部署对于培养一代又一代德智体美劳全面发展的社会主义建设者和接班人，培养一代又一代在社会主义现代化建设中可堪大用、能担重任的栋梁之材，确保党的事业和社会主义现代化建设后继有人具有重要意义。第一，加强党对教育工作的全面领导。这是办好教育的根本保证。第二，锻造好落实立德树人根本任务的关键课程。聚焦用习近平新时代中国特色社会主义思想铸魂育人，坚持思政课建设与党的创新理论武装同步推进，加快构建以习近平新时代中国特色社会主义思想为核心内容的课程教材体系。办好思政课关键在教师。要配齐思政课教师和思政工作队伍，切实提高教师综合素质，建设一支政治强、情怀深、思维新、视野广、自律严、人格正的思政课教师队伍。第三，拓展实践育人和网络育人重要阵地。统筹推动价值引领、实践体验与环境营造，探索课上课下协同、校内校外一体、线上线下融合的育人机制。第四，促进学生健康成长、全面发展。全面落实健康第一教育理念，实施学生体质强健计划，引导学生养成良好锻炼习惯和健康生活方式，有效控制近视率、肥胖率。第五，完善教育评价体系。坚持把立德树人成效作为评价学校的根本标准，坚决克服重分数轻素质等片面办学行为，促进学生身心健康、全面发展。坚持把师德师风作为评价教师的第一标准，弘扬教育家精神，引导广大教师践行教书育人使命。（⑤错误）故本题选C。"
