     "e": "社保基金是社会保障体系运行的重要基础。《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提出：“健全社保基金长效筹集、统筹调剂、保值增值和安全监管机制。”社保基金按保障层次来划分，主要包括社会保险基金、补充保险基金、国家社会保障储备基金等。社会保险基金是社保基金中最重要的组成部分，包括基本养老保险基金、基本医疗保险基金、工伤保险基金、失业保险基金和生育保险基金，除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账、分账核算。未来社保基金可持续运行的压力增加，需要及早防范、综合应对。第一，健全社保基金长效筹集机制。深入实施全民参保计划，全面取消在就业地参保户籍限制，完善社保关系转移接续政策，优化基金征缴管理，促进更多灵活就业人员、农民工、新就业形态人员等参保，不断扩大社保覆盖面。推动将更多符合企业职工参保条件的人员纳入企业职工基本养老保险、企业职工基本医疗保险，扩大这两项社保基金规模。进一步明确财政支持社保基金责任，优化财政补贴机制。继续划转国有资本充实社保基金。第二，健全社保基金统筹调剂机制。完善并落实企业职工基本养老保险全国统筹制度。持续推进基本医疗保险及生育保险省级统筹。第三，健全社保基金保值增值机制。促进社保基金保值增值，增强社保制度的造血功能和自我平衡能力。第四，健全社保基金安全监管机制。完善政策、经办、信息、监督“四位一体”风险防控机制，强化人防、制防、技防、群防“四防协同”，保障基金安全。B项错误，住房公积金不属于社会保险基金。故本题选B。"
