     "a": 1,
     "e": "2026年4月，中共中央办公厅、国务院办公厅印发《碳达峰碳中和综合评价考核办法》。A项正确，评价考核设置控制指标、支撑指标。控制指标包括碳排放总量、碳排放强度降低、煤炭消费总量、石油消费总量、非化石能源消费占比等指标。支撑指标包括节能、工业、城乡建设、交通运输、公共机构、碳排放权交易等领域具有代表性且对碳达峰碳中和具有支撑作用的指标。B项正确，“十五五”时期，国家发展改革委应当会同有关部门围绕如期实现2030年前碳达峰目标，制定“十五五”碳达峰行动方案，确保实现2030年碳排放强度比2005年降低65%以上、2030年非化石能源消费占比达到25%等目标，实现煤炭消费总量和石油消费总量达峰，合理控制煤电装机规模和发电量，力争年度新增清洁能源电量逐步覆盖全社会新增用电量。C项正确，评价考核工作按照年度开展，于评价考核年度次年具体实施。各省（自治区、直辖市）党委和政府对本地区年度碳达峰碳中和工作开展自评，并按时将自评报告报党中央、国务院，抄送国家发展改革委等评价考核负责部门。国家发展改革委会同有关部门进行实地核验。国家发展改革委结合地方自评、部门评价、实地核验等情况，按照优秀、合格、不合格3个等次提出各省（自治区、直辖市）年度碳达峰碳中和综合评价考核结果建议，商中央组织部后按照程序报党中央、国务院。D项错误，控制指标和支撑指标全部达标的省（自治区、直辖市），评价考核结果为“优秀”；1项及以上控制指标不达标或者3项及以上支撑指标不达标的省（自治区、直辖市），评价考核结果为“不合格”；其余为“合格”。故本题选D。"
