     "e": "2026年4月24日，正值第十一个“中国航天日”，国家航天局对外发布嫦娥五号月球样品最新研究成果：中国科学家在嫦娥五号月球样品中，发现两种月球新矿物，均获国际矿物学协会新矿物、矿物命名及分类委员会批准，分别命名为镁嫦娥石与铈嫦娥石。这是继2022年嫦娥石之后，中国科学家在返回月壤中发现的第二种和第三种月球新矿物，也是全世界在返回月壤中发现的第七和第八种月球新矿物。其中，镁嫦娥石发现于我国嫦娥五号月球探测器带回的月壤样品之中，产出于月球钻取玄武岩碎屑内部。镁嫦娥石呈柱状晶体，迄今在地球上还没有发现完全相同的对应矿物。故本题选B。"
