     "e": "2025年度全国十大考古新发现4月29日在北京揭晓。吉林东部长白山旧石器时代遗址群、河南新郑裴李岗遗址、河北宣化郑家沟遗址、甘肃庆阳南佐遗址、山西昔阳钟村遗址、河南郑州商城遗址、陕西富平长春遗址、山东青岛琅琊台遗址、浙江绍兴越国都城和汉六朝会稽郡遗址、宁夏贺兰苏峪口瓷窑址入选。吉林东部长白山旧石器时代遗址群，以丰富且独特的黑曜岩石器工业遗存，清晰记录了距今约22万年至1.3万年古人类的技术演进与适应发展历程，深刻影响东北亚史前文化发展格局，见证了东北亚史前跨区域文化交流进程，是中华文明远古根脉的关键组成部分。山西昔阳钟村遗址的墓葬是迄今发现等级最高的夏晚期贵族墓葬群，显示出太行山西麓存在着一个独立的区域中心，为衡量二里头文化和下七垣文化的文明发展高度和社会等级分化程度提供了重要参照。遗址所见来自远方的各类奢侈品，正是中华民族多元一体格局的生动体现。山东青岛琅琊台遗址是目前发现的东部地区时代最早、规模最大的秦帝国国家工程，填补了秦汉时期关中以外高台建筑考古的空白，集中展现了早期封建王朝国家治理能力、工程技术水平及文化整合策略，是研究中华文明多元一体的演进机制的绝佳例证。甘肃庆阳南佐遗址代表了仰韶文化发展的最高峰，应该是黄土高原距今5000年前后的一处都邑性聚落。聚落核心区以中轴线统一规划和布局，表明距今5000年前后已经基本形成了古代城市的中轴线格局。如此规模巨大聚落的营建，体现出强大的社会组织调动能力，是黄土高原出现区域王权的有力证明。C项错误，山东青岛琅琊台遗址是目前发现的东部地区时代最早、规模最大的秦帝国国家工程。故本题选C。"
