     "e": "2026年7月8日，习近平总书记在“科技三会”（即国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表大会）上发表重要讲话，就全力抓好党中央关于科技事业各项部署的落实提出6点明确要求，其中排在首位的是“增强科技创新体系化攻关能力”。科技创新涉及领域、主体、要素多，是一个庞大的系统。必须坚持“四个面向”战略导向，充分发挥新型举国体制优势，进一步加强各方面统筹，整合资源力量，提高科技攻关组织化程度，提升国家创新体系整体效能。要完善国家重大科技创新任务部署和组织实施机制，统筹推进原始创新和关键核心技术攻关；要优化国家战略科技力量功能定位和布局，推动任务协同、资源共享、优势互补；要加强对各层级科技工作的统筹指导，形成央地协同、区域联动的制度安排。运用系统思维，加强统筹协调，让攻关能力不断强化、让创新合力不断集聚、让创新突破不断涌现。（摘自新华社2026年7月8日文章《学习快评丨增强科技创新体系化攻关能力》）（“十五五”时期是科技强国建设的关键攻坚期，要全力抓好党中央关于科技事业各项部署的落实。习近平总书记强调6点：增强科技创新体系化攻关能力、推动科技创新和产业创新深度融合、大力培养优秀青年科技人才、提高科技创新投入效能、用好科技评价指挥棒、加强科技伦理和安全治理。——编者注）"
